from __future__ import annotations

import html
import json
from typing import Any


def _json_for_script(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False).replace("</", "<\\/")


def render_html(result: dict[str, Any], case: dict[str, Any]) -> str:
    subject = result.get("subject", {})
    title = html.escape(str(subject.get("name", "Ownership & Control")))
    payload = _json_for_script({"result": result, "case": case})
    return f'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="Evidence-first ownership and control investigation workspace.">
<title>SafeTrace Intelligence Desk — {title}</title>
<style>
:root{{--bg:#f4f5f1;--surface:#fff;--ink:#101310;--muted:#68706a;--line:#dfe3dc;--green:#126b50;--green2:#e7f3ed;--amber:#9a5b08;--amber2:#fff4df;--blue:#315e82;--blue2:#edf5fb;--radius:18px}}
*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,sans-serif}}button{{font:inherit;cursor:pointer}}.top{{height:62px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 26px;background:rgba(244,245,241,.94)}}.brand{{font-weight:850;letter-spacing:-.02em}}.brand small{{display:block;font-size:10px;color:var(--muted);font-weight:650}}.pill{{border:1px solid var(--line);border-radius:999px;padding:5px 9px;font-size:10px;color:var(--muted);background:#fff}}.hero{{max-width:1450px;margin:auto;padding:32px 26px 20px}}.eyebrow{{font-size:10px;text-transform:uppercase;letter-spacing:.12em;font-weight:850;color:var(--green)}}h1{{font-size:clamp(32px,4.7vw,58px);line-height:1;letter-spacing:-.05em;margin:8px 0 10px}}.hero p{{font-size:16px;color:#4c554f;max-width:830px;margin:0}}.workspace{{max-width:1450px;margin:auto;padding:0 26px 70px;display:grid;grid-template-columns:250px minmax(520px,1fr) 320px;gap:14px}}.panel{{background:#fff;border:1px solid var(--line);border-radius:var(--radius);overflow:hidden}}.left,.right{{padding:17px;height:max-content;position:sticky;top:14px}}.label{{font-size:9px;text-transform:uppercase;letter-spacing:.12em;font-weight:850;color:var(--muted);margin-bottom:8px}}.subject{{display:flex;gap:10px;align-items:center;margin-bottom:13px}}.icon{{width:40px;height:40px;border-radius:11px;background:#111;color:white;display:grid;place-items:center;font-weight:850}}.subject b{{font-size:15px;line-height:1.2;display:block}}.subject span{{font-size:10px;color:var(--muted)}}.verdict{{background:var(--green2);border:1px solid #d2e6dc;border-radius:12px;padding:12px;margin:13px 0 17px}}.verdict b{{font-size:12px;color:#0e5c43}}.verdict p{{font-size:10px;color:#446252;margin:4px 0 0}}.facts{{border-top:1px solid var(--line)}}.fact{{display:flex;justify-content:space-between;gap:8px;padding:9px 0;border-bottom:1px solid #edf0eb;font-size:10px}}.fact span{{color:var(--muted)}}.fact b{{text-align:right}}.answer{{padding:18px 20px;border-bottom:1px solid var(--line)}}.answer h2{{font-size:20px;letter-spacing:-.03em;margin:4px 0 7px}}.answer p{{font-size:12px;color:#566058;margin:0;max-width:820px}}.stats{{display:flex;gap:6px;flex-wrap:wrap;margin-top:11px}}.stat{{font-size:9px;border:1px solid var(--line);border-radius:999px;padding:4px 7px;color:var(--muted)}}.graph-title{{display:flex;justify-content:space-between;padding:13px 16px 4px}}.graph-title b{{font-size:11px}}.graph-title span{{font-size:9px;color:var(--muted)}}#graph{{height:470px;background:radial-gradient(circle at 50% 40%,#fff,#f8faf7);position:relative}}svg{{width:100%;height:100%}}.edge{{stroke:#aab4ac;stroke-width:1.6;fill:none}}.edge.dashed{{stroke:#d1a15d;stroke-dasharray:5 5}}.hit{{stroke:transparent;stroke-width:18;fill:none;cursor:pointer}}.elabel{{font-size:10px;font-weight:850;fill:#263028}}.esub{{font-size:8px;fill:#788179}}.node{{cursor:default}}.node rect{{fill:#fff;stroke:#ccd2cb;rx:11;filter:url(#shadow)}}.node.target rect{{stroke:#111;stroke-width:1.5}}.node text.t{{font-size:10px;font-weight:850;fill:#111}}.node text.s{{font-size:8px;fill:#737d76}}.empty{{height:100%;display:grid;place-items:center;text-align:center;padding:30px}}.empty div{{max-width:460px}}.empty i{{font-style:normal;font-size:25px;display:block;margin-bottom:8px}}.empty h3{{margin:0 0 6px;font-size:18px}}.empty p{{margin:0;color:var(--muted);font-size:11px}}.tabs{{display:grid;grid-template-columns:1fr 1fr;margin:-17px -17px 16px;border-bottom:1px solid var(--line)}}.tab{{border:0;background:transparent;padding:12px;font-size:10px;font-weight:800;color:var(--muted)}}.tab.active{{color:#111;box-shadow:inset 0 -2px #111}}.finding{{border:1px solid #e8ebe6;background:#f8f9f7;border-radius:11px;padding:10px;margin-bottom:7px}}.finding.warn{{background:var(--amber2);border-color:#efddbc}}.finding b{{font-size:10px;display:block}}.finding p{{font-size:9px;color:var(--muted);margin:3px 0 0}}.next{{margin-top:15px;background:#111;color:white;border-radius:13px;padding:13px}}.next .label{{color:#abb4ad}}.next b{{font-size:11px;display:block}}.next p{{font-size:9px;color:#c8cec9;margin:5px 0 0}}.evidence-empty{{text-align:center;color:var(--muted);padding:35px 7px;font-size:10px}}.relation{{display:inline-block;background:var(--blue2);color:var(--blue);border-radius:999px;padding:4px 7px;font-size:9px;font-weight:850}}.evidence h3{{font-size:14px;line-height:1.25;margin:9px 0}}.calc{{font:10px/1.45 ui-monospace,SFMono-Regular,Menlo,monospace;background:#f7f8f6;border:1px solid var(--line);border-radius:9px;padding:9px;margin:10px 0}}.source{{border:1px solid var(--line);border-radius:10px;padding:9px;margin-top:7px}}.source b{{display:block;font-size:9px}}.source span{{display:block;font-size:8px;color:var(--muted);margin-top:2px}}.boundary{{font-size:9px;color:var(--muted);margin-top:12px}}.hidden{{display:none!important}}@media(max-width:1080px){{.workspace{{grid-template-columns:220px 1fr}}.right{{grid-column:1/-1;position:static}}}}@media(max-width:720px){{.workspace{{grid-template-columns:1fr;padding:0 14px 50px}}.hero{{padding:25px 14px 17px}}.left{{position:static;order:2}}.center{{order:1}}.right{{order:3}}#graph{{height:390px}}.top{{padding:0 14px}}}}
</style>
</head>
<body>
<header class="top"><div class="brand">SafeTrace <small>Intelligence Desk</small></div><span class="pill">Evidence-first work product</span></header>
<section class="hero"><div class="eyebrow">Ownership & control investigation</div><h1 id="headline"></h1><p id="subhead"></p></section>
<main class="workspace">
<aside class="panel left"><div class="label">Target</div><div class="subject"><div class="icon" id="icon"></div><div><b id="subject"></b><span id="caseMeta"></span></div></div><div class="verdict"><b id="verdictTitle"></b><p id="verdictText"></p></div><div class="label">At a glance</div><div class="facts" id="facts"></div></aside>
<section class="panel center"><div class="answer"><div class="label">Executive answer</div><h2>What can we responsibly conclude?</h2><p id="answer"></p><div class="stats" id="stats"></div></div><div class="graph-title"><b>Ownership map</b><span>Click any relationship to inspect its evidence</span></div><div id="graph"></div></section>
<aside class="panel right"><div class="tabs"><button class="tab active" data-tab="brief">Analyst brief</button><button class="tab" data-tab="evidence">Evidence</button></div><div id="brief"><div class="label">What matters</div><div id="findings"></div><div class="next"><div class="label">Best next action</div><b id="nextTitle"></b><p id="nextText"></p></div></div><div id="evidence" class="hidden"><div class="evidence-empty">Select a relationship in the graph to see the source, anchor, calculation and analytical boundary.</div></div></aside>
</main>
<script id="payload" type="application/json">{payload}</script>
<script>
const data=JSON.parse(document.getElementById('payload').textContent),r=data.result,c=data.case;
const entities=Object.fromEntries((c.entities||[]).map(x=>[x.id,x])),sources=Object.fromEntries((c.sources||[]).map(x=>[x.id,x]));
const target=entities[c.target_entity_id]||r.subject||{{name:'Unknown target'}};
const pct=x=>x==null?'unknown':`${{Math.round(x*10000)/100}}%`;const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[m]));
const initials=(target.name||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
document.getElementById('icon').textContent=initials;document.getElementById('subject').textContent=target.name;document.getElementById('caseMeta').textContent=`${{r.case_id}} · ${{r.classification||'case'}}`;document.getElementById('headline').textContent=`Who owns and controls ${{target.name}}?`;document.getElementById('subhead').textContent='SafeTrace separates economic ownership, voting rights and other control, preserves the evidence behind each relationship, and keeps missing evidence visibly unresolved.';
const economic=r.economic_ownership||[],ubo=r.ubo_candidates||[],gaps=r.unresolved||[],control=r.control_signals||[];
const top=economic[0];let verdictTitle='Ownership not established',verdictText='The supplied evidence does not establish an ownership chain.';if(economic.length){{verdictTitle=r.decision_boundary?.beneficial_ownership_complete?'Beneficial ownership complete':'Ownership partly established';verdictText=r.decision_boundary?.beneficial_ownership_complete?'The bounded ownership chain is affirmatively complete under the supplied evidence.':'Some ownership relationships are established, but open evidence gaps remain.'}}
document.getElementById('verdictTitle').textContent=verdictTitle;document.getElementById('verdictText').textContent=verdictText;
const factRows=[['Established edges',r.metrics?.established_edges||0],['Top economic path',top?`${{top.owner_name}} · ${{pct(top.aggregate_pct)}}`:'None'],['UBO candidates',ubo.length],['Open items',r.metrics?.unresolved_items||0]];document.getElementById('facts').innerHTML=factRows.map(x=>`<div class="fact"><span>${{esc(x[0])}}</span><b>${{esc(x[1])}}</b></div>`).join('');
let answer='No ownership conclusion is supported by the supplied evidence.';if(economic.length){{const direct=economic.filter(x=>x.paths?.some(p=>p.direct)).slice(0,3).map(x=>`${{x.owner_name}} (${{pct(x.aggregate_pct)}})`).join(', ');answer=`The evidence establishes ${{economic.length}} economic ownership position${{economic.length===1?'':'s'}}${{direct?`, including direct positions held by ${{direct}}`:''}}. ${{ubo.length?`${{ubo.length}} natural-person candidate${{ubo.length===1?'':'s'}} meet the configured analytical rule.`:'No natural-person UBO candidate is established yet.'}} ${{gaps.length?`${{gaps.length}} unresolved item${{gaps.length===1?' remains':'s remain'}} visible.`:'No unresolved item remains in this bounded case.'}}`}}document.getElementById('answer').textContent=answer;document.getElementById('stats').innerHTML=[`${{economic.length}} ownership positions`,`${{control.length}} control signals`,`${{gaps.length}} unresolved`].map(x=>`<span class="stat">${{esc(x)}}</span>`).join('');
const findings=[];if(top)findings.push([false,`${{top.owner_name}} · ${{pct(top.aggregate_pct)}} economic`,`Highest aggregated economic position in the computed graph.`]);if(ubo.length)findings.push([false,`${{ubo.length}} rule-scoped UBO candidate${{ubo.length===1?'':'s'}}`,ubo.map(x=>x.name).join(', ')]);if(gaps.length)findings.push([true,`${{gaps.length}} unresolved evidence item${{gaps.length===1?'':'s'}}`,gaps[0].reason||'Additional evidence is required.']);if(!findings.length)findings.push([true,'No ownership evidence established','The correct analytical result is to keep the graph empty.']);document.getElementById('findings').innerHTML=findings.map(x=>`<div class="finding ${{x[0]?'warn':''}}"><b>${{esc(x[1])}}</b><p>${{esc(x[2])}}</p></div>`).join('');
const firstGap=gaps.find(x=>x.reason)||null;document.getElementById('nextTitle').textContent=firstGap?'Close the highest-value evidence gap':'Review the completed ownership chain';document.getElementById('nextText').textContent=firstGap?.reason||'Validate jurisdiction-specific ownership/control rules before consequential use.';
function depths(){{const incoming={{}};(c.ownership_edges||[]).forEach(e=>(incoming[e.target_id]??=[]).push(e.owner_id));const d={{[c.target_entity_id]:0}},q=[c.target_entity_id];while(q.length){{const id=q.shift();for(const owner of incoming[id]||[])if(d[owner]==null){{d[owner]=d[id]+1;q.push(owner)}}}}return d}};
function graph(){{const edges=(c.ownership_edges||[]),est=edges.filter(e=>e.status==='established'),g=document.getElementById('graph');if(!est.length){{g.innerHTML='<div class="empty"><div><i>⌁</i><h3>No ownership edge is supported yet</h3><p>SafeTrace leaves the map empty rather than converting a company mention, manager or website profile into an ownership claim.</p></div></div>';return}}const d=depths(),levels={{}};Object.entries(d).forEach(([id,n])=>(levels[n]??=[]).push(id));const max=Math.max(...Object.values(d)),W=760,H=450,pos={{}},nw=164,nh=55;Object.entries(levels).forEach(([ds,ids])=>{{const depth=+ds,y=365-depth*(285/Math.max(max,1));ids.forEach((id,i)=>{{const gap=W/(ids.length+1);pos[id]={{x:gap*(i+1)-nw/2,y:y-nh/2}}}})}});const defs='<defs><filter id="shadow"><feDropShadow dx="0" dy="3" stdDeviation="5" flood-opacity=".07"/></filter><marker id="a" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10z" fill="#aab4ac"/></marker></defs>';const lines=edges.map(e=>{{const a=pos[e.owner_id],b=pos[e.target_id];if(!a||!b)return'';const x1=a.x+nw/2,y1=a.y+nh,x2=b.x+nw/2,y2=b.y,my=(y1+y2)/2,mx=(x1+x2)/2,unknown=e.status!=='established'||e.economic_pct==null;return `<g><path class="edge ${{unknown?'dashed':''}}" d="M${{x1}} ${{y1}} C${{x1}} ${{my}} ${{x2}} ${{my}} ${{x2}} ${{y2}}" marker-end="url(#a)"/><path class="hit" data-edge="${{esc(e.id)}}" d="M${{x1}} ${{y1}} C${{x1}} ${{my}} ${{x2}} ${{my}} ${{x2}} ${{y2}}"/><rect x="${{mx-34}}" y="${{my-14}}" width="68" height="25" rx="7" fill="#fff" stroke="#e0e4de"/><text class="elabel" x="${{mx}}" y="${{my-1}}" text-anchor="middle">${{esc(pct(e.economic_pct))}}</text><text class="esub" x="${{mx}}" y="${{my+8}}" text-anchor="middle">economic</text></g>`}}).join('');const nodes=Object.entries(pos).map(([id,p])=>{{const e=entities[id]||{{name:id,kind:'other'}},cls=id===c.target_entity_id?'target':'';return `<g class="node ${{cls}}" transform="translate(${{p.x}},${{p.y}})"><rect width="${{nw}}" height="${{nh}}"/><text class="t" x="12" y="21">${{esc(e.name.length>24?e.name.slice(0,23)+'…':e.name)}}</text><text class="s" x="12" y="38">${{esc((e.kind||'entity').toUpperCase())}} · ${{esc(e.resolution_status||'unresolved')}}</text></g>`}}).join('');g.innerHTML=`<svg viewBox="0 0 ${{W}} ${{H}}">${{defs}}${{lines}}${{nodes}}</svg>`;document.querySelectorAll('[data-edge]').forEach(x=>x.onclick=()=>showEvidence(edges.find(e=>e.id===x.dataset.edge)))}};
function showEvidence(edge){{document.querySelector('[data-tab="evidence"]').click();const srcs=(edge.evidence||[]).map(ev=>{{const s=sources[ev.source_id]||{{title:ev.source_id}};return `<div class="source"><b>${{esc(s.title||ev.source_id)}}</b><span>${{esc(ev.source_id)}} · ${{esc(ev.anchor)}}</span></div>`}}).join('')||'<div class="source"><b>No sufficient evidence</b><span>This relationship is not established.</span></div>';const owner=entities[edge.owner_id]?.name||edge.owner_id,tgt=entities[edge.target_id]?.name||edge.target_id;document.getElementById('evidence').innerHTML=`<span class="relation">${{edge.status==='established'?'ESTABLISHED RELATIONSHIP':'UNRESOLVED RELATIONSHIP'}}</span><h3>${{esc(owner)}} → ${{esc(tgt)}}</h3><div class="calc">economic: ${{esc(pct(edge.economic_pct))}} · voting: ${{esc(pct(edge.voting_pct))}}</div><div class="label">Evidence</div>${{srcs}}<p class="boundary">Economic ownership, voting rights and other control are separate evidence dimensions. This relationship is bounded by the supplied sources and still requires human review for consequential use.</p>`}};
document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===t));document.getElementById('brief').classList.toggle('hidden',t.dataset.tab!=='brief');document.getElementById('evidence').classList.toggle('hidden',t.dataset.tab!=='evidence')}});graph();
</script>
</body></html>'''
